mapper.select:
SELECT T.* FROM (SELECT A.*, D.TESTNAME, C.METHODNAME, C.TESTMETHODBASIS, B.METHODID, B.TESTCATEGORYID, B.ACTIVATEDFLAG AS SHOWFLAG, B.ISLOCKED, B.DEFAULTFLAG FROM T_EMC_ITEM_GROUP A LEFT JOIN T_EMC_TEST_METHOD B ON A.TESTMETHODID = B.ID LEFT JOIN T_EMC_METHOD C ON B.METHODID = C.ID LEFT JOIN T_EMC_TEST D ON B.TESTID = D.ID WHERE B.ACTIVATEDFLAG = '1' ) T
AND NOT EXISTS (SELECT 1 FROM ${targetTable} TAR_ WHERE TAR_.${targetItemGroupIdColumn} = T.ID
AND TAR_.${targetFilterColumn} = #{targetFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND NOT EXISTS (SELECT 1 FROM T_EMC_TEST_CAPACITY TC LEFT JOIN T_EMC_CAPACITY_ITEM_GROUP M ON TC.ID = M.TESTCAPACITYID WHERE M.ITEMGROUPID = T.ID AND TC.ORGID = #{loginUser.ext$.parentorgid} )
ORDER BY
T.ID DESC

SELECT T.*
  FROM T_EMC_ITEM_GROUP T
 WHERE T.ID = #{id}
